namespace elit21::shopify::webhooks {ShopifyWebhookReceiver::ShopifyWebhookReceiver():platform::BusinessComponent("ShopifyWebhookReceiver","Authenticated Shopify webhook receiver",platform::BusinessComponentSpec{"shopify","receive_webhook",{},true,true,16U*1024U*1024U}){}ShopifyWebhookReceiver::ShopifyWebhookReceiver(std::string secret,ShopifyWebhookDispatcher&dispatcher):ShopifyWebhookReceiver(){bind(std::move(secret),dispatcher);}void ShopifyWebhookReceiver::bind(std::string secret,ShopifyWebhookDispatcher&dispatcher){verifier_.setSecret(std::move(secret));dispatcher_=&dispatcher;}OutgoingResponse ShopifyWebhookReceiver::receive(const IncomingRequest&r){if(!verifier_.verify(r))return{401,"application/json","{\"error\":\"invalid_hmac\"}"};auto event=parser_.parse(r);if(!event)return{400,"application/json","{\"error\":\"invalid_webhook\"}"};if(!dispatcher_)return{503,"application/json","{\"error\":\"dispatcher_unavailable\"}"};auto handled=dispatcher_->dispatch(event.value());if(!handled)return{422,"application/json","{\"error\":\"handler_failed\"}"};return{202,"application/json","{\"accepted\":true}"};}platform::OperationResult ShopifyWebhookReceiver::execute(const platform::OperationContext&context){auto r=executeBusiness(context);r.metrics["dispatcher_bound"]=dispatcher_?1.0:0.0;r.attributes["hmac_required"]="true";return r;}}
